package top.monitorglobal.tv;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** The producer palette stays untouched; bitmap ownership belongs to the presenter. */
final class WeatherSatelliteCard extends LinearLayout {
 private final ImageView map,legend;
 WeatherSatelliteCard(Context c,WeatherSatelliteClient.Frame frame,boolean large){super(c);setOrientation(VERTICAL);GradientDrawable bg=new GradientDrawable();bg.setColor(WeatherCardView.BODY);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),WeatherCardView.CYAN);setBackground(bg);setPadding(dp(10),dp(7),dp(10),dp(8));label("SATÉLITE · "+frame.scope.name,large?23:17,WeatherCardView.CYAN);map=new ImageView(c);map.setScaleType(ImageView.ScaleType.FIT_CENTER);map.setContentDescription("Imagem infravermelha do "+frame.scope.name+" com referência de São Paulo");map.setImageBitmap(frame.image);addView(map,new LayoutParams(-1,large?0:dp(225),large?1:0));label("Temperatura de brilho · °C",large?16:12,Color.WHITE);legend=new ImageView(c);legend.setBackgroundColor(Color.WHITE);legend.setScaleType(ImageView.ScaleType.FIT_CENTER);legend.setContentDescription("Legenda original de temperatura infravermelha NASA");if(frame.legend!=null){legend.setImageBitmap(frame.legend);addView(legend,new LayoutParams(-1,dp(55)));}else label("Legenda da fonte indisponível",12,WeatherCardView.MUTED);label(InfraredPlan.timing(frame.at,System.currentTimeMillis()),large?16:12,System.currentTimeMillis()-frame.at>InfraredPlan.FRESH_AGE?0xffffcf7e:Color.WHITE);label("GOES-East · NASA GIBS / NOAA",large?14:12,WeatherCardView.MUTED);label("Infravermelho · não mede intensidade da chuva",large?14:11,WeatherCardView.MUTED);}
 private void label(String s,int size,int color){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setMaxLines(2);t.setIncludeFontPadding(false);t.setPadding(0,dp(2),0,dp(2));addView(t,new LayoutParams(-1,-2));}
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 void clear(){map.setImageDrawable(null);legend.setImageDrawable(null);}
}
